CREATE  TABLE "PUBLIC"."ESTANCIA"(
    "ACTIVO" BOOLEAN,
    "MES_ACTUAL" BOOLEAN,
    "MONTO_PAGAR" FLOAT,
    "TIEMPO_MINUTOS" INTEGER,
    "FECHA_ENTRADA" TIMESTAMP(6) NOT NULL,
    "FECHA_SALIDA" TIMESTAMP(6),
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "VEHICULO_ID" BIGINT
);
ALTER TABLE "PUBLIC"."ESTANCIA" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_B" PRIMARY KEY("ID");

CREATE  TABLE "PUBLIC"."TIPO_VEHICULO"(
    "TARIFA" FLOAT,
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "DESCRIPCION" CHARACTER VARYING(255) NOT NULL
);
ALTER TABLE "PUBLIC"."TIPO_VEHICULO" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_A" PRIMARY KEY("ID");

CREATE  TABLE "PUBLIC"."VEHICULO"(
    "FECHA_REGISTRO" TIMESTAMP(6),
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "TIPO_VEHICULO_ID" BIGINT,
    "PLACA" CHARACTER VARYING(255) NOT NULL
);
ALTER TABLE "PUBLIC"."VEHICULO" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_A6" PRIMARY KEY("ID");

ALTER TABLE "PUBLIC"."ESTANCIA" ADD CONSTRAINT "PUBLIC"."FK5D26MSWFQRQ5BJKSIMB0QR2OC" FOREIGN KEY("VEHICULO_ID") REFERENCES "PUBLIC"."VEHICULO"("ID") NOCHECK;

ALTER TABLE "PUBLIC"."VEHICULO" ADD CONSTRAINT unique_placa UNIQUE ("PLACA");
ALTER TABLE "PUBLIC"."VEHICULO" ADD CONSTRAINT "PUBLIC"."FK8SI429JG12XPNU65GSN2A1R44" FOREIGN KEY("TIPO_VEHICULO_ID") REFERENCES "PUBLIC"."TIPO_VEHICULO"("ID") NOCHECK;
